package com.mo.economy_system.target.neoforge1211.client;
import com.mo.economy_system.common.network.CheckedFileTransferControlResponseMessage;import com.mo.economy_system.common.transfer.*;import java.io.IOException;import java.nio.file.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
final class Screen_CheckedFileTransferResult extends Screen{private final CheckedFileTransferControlResponseMessage message;private final Path temp;private final CheckedFileTransferControl control;Screen_CheckedFileTransferResult(CheckedFileTransferControlResponseMessage m,Path p,CheckedFileTransferControl c){super(Component.translatable("screen.transfer_result.title"));message=m;temp=p;control=c;}protected void init(){if(width<110||height<120)return;addRenderableWidget(Button.builder(Component.translatable("button.transfer.save"),b->save()).bounds(width/2-105,height-25,100,20).build());addRenderableWidget(Button.builder(Component.translatable("button.transfer.discard"),b->discard()).bounds(width/2+5,height-25,100,20).build());}public void render(GuiGraphics g,int x,int y,float p){super.render(g,x,y,p);g.drawCenteredString(font,title,width/2,18,0xffffff);if(height>=90){g.drawString(font,Component.translatable("screen.transfer_result.source",message.targetPlayerName()),12,42,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_result.file",message.fileName()),12,54,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_result.size",control.byteLength()),12,66,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_result.hash",control.sha256()),12,78,0xdddddd);}}private void save(){try{Path dir=Minecraft.getInstance().gameDirectory.toPath().resolve("economy_system").resolve("received-check-files").resolve(message.targetPlayerId().toString());Files.createDirectories(dir);String name=message.fileName();Path target=dir.resolve(name);for(int i=1;Files.exists(target,LinkOption.NOFOLLOW_LINKS)&&i<=100;i++)target=dir.resolve(i+"-"+name);Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE);Minecraft.getInstance().setScreen(null);}catch(IOException ignored){}}private void discard(){try{Files.deleteIfExists(temp);}catch(IOException ignored){}Minecraft.getInstance().setScreen(null);}public void onClose(){discard();}}
